    'west': 'west'
  };
  const zone = locationMap[data.location?.toLowerCase()];
  if (!zone) return null;

  let status = 'normal';
  if (metric === 'temperature') {
    if (value > 40 || value < -5) status = 'critical';
    else if (value > 30 || value < 0) status = 'warning';
  } else if (metric === 'humidity') {
    if (value > 90) status = 'critical';
    else if (value > 75) status = 'warning';
  } else if (metric === 'pressure') {
    if (value < 960 || value > 1040) status = 'critical';
    else if (value < 980 || value > 1030) status = 'warning';
