    if (c === '"') inQuotes = !inQuotes;
    else if (c === ',' && !inQuotes) { parts.push(current); current = ''; }
    else current += c;
  }
  parts.push(current);
  data = {
    time: parts[0],
    lat: parseFloat(parts[1]),
    lon: parseFloat(parts[2]),
    depth: parseFloat(parts[3]),
    mag: parseFloat(parts[4]),
    magType: parts[5],
    id: parts[11],
    place: parts[13],
    type: parts[14],
    status: parts[19],
    sig: parseInt(parts[6]) // nst is at 6, sig not in standard CSV
  };
  data.sig = null;
  const fullCsv = e;
  const sigMatch = fullCsv.match(/,(\d+),/g);
}

const validMagTypes = ['ml', 'md', 'mb', 'mw', 'mww', 'mwb', 'mwc', 'mwr', 'ms', 'mb_lg', 'mi', 'mh'];
const magType = (data.magType || '').toLowerCase();
if (!validMagTypes.includes(magType)) return null;

const lat = typeof data.lat === 'number' ? data.lat : parseFloat(data.lat);
const lon = typeof data.lon === 'number' ? data.lon : parseFloat(data.lon);
const depth = typeof data.depth === 'number' ? data.depth : parseFloat(data.depth);
const mag = typeof data.mag === 'number' ? data.mag : parseFloat(data.mag);

if (!data.id || typeof data.id !== 'string' || !data.id.trim()) return null;
if (isNaN(mag)) return null;
if (isNaN(lat) || lat < -90 || lat > 90) return null;
if (isNaN(lon) || lon < -180 || lon > 180) return null;
if (isNaN(depth) || depth < 0 || depth > 800) return null;
if (!data.place || typeof data.place !== 'string' || !data.place.trim()) return null;
if (!data.type || typeof data.type !== 'string') return null;

const status = data.status === 'reviewed' ? 'reviewed' : data.status === 'automatic' ? 'automatic' : null;
if (!status) return null;

let timestamp;
if (typeof data.time === 'number') {
  const d = new Date(data.time);
  timestamp = d.toISOString().replace(/\.\d{3}Z$/, 'Z');
} else if (typeof data.time === 'string') {
  const d = new Date(data.time);
  if (isNaN(d.getTime())) return null;
  timestamp = d.toISOString().replace(/\.\d{3}Z$/, 'Z');
} else return null;

let sig = data.sig;
if (sig === null || sig === undefined) {
  sig = 0;
} else {
  sig = parseInt(sig);
  if (isNaN(sig) || sig < 0 || sig > 2500) return null;
}

return {
  event_id: data.id.trim(),
  magnitude: mag,
  magnitude_type: magType,
  latitude: lat,
  longitude: lon,
  timestamp_utc: timestamp,
  place: data.place.trim(),
  event_type: data.type,
  status: status,
  depth_km: depth,
  significance: sig
};
